    const img=(u,alt='Business visual',cls='')=>u?`<img src="${esc(u)}" alt="${esc(alt)}" class="${cls}" style="width:100%;height:100%;object-fit:cover;display:block" onerror="this.style.display='none'">`:'';
    const galleryImgs=[heroImg,aboutImg,...(t.image_urls||[])].filter(Boolean).slice(0,6);
