    const cards=features.map((f,i)=>`<div style="padding:16px;border-radius:${i%2?18:28}px;background:${i%2?'#fff':accent+'18'};border:1px solid ${bg}18;box-shadow:0 12px 30px #0000000d;transform:${i%3===0?'translateY(-4px)':'none'}"><div style="width:42px;height:42px;border-radius:${i%2?'12px':'50%'};background:${accent};color:#111;display:grid;place-items:center;font-weight:900;font-size:18px">${['✦','✓','◆','↗','★','◉'][i]}</div><h4 style="margin:10px 0 5px;color:${bg}">${esc(f)}</h4><p class="muted" style="font-size:11px;margin:0">Premium ${esc(t.category||'business')} experience designed for real customers.</p></div>`).join('');
    const metrics=`<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:${bg}18;border-radius:18px;overflow:hidden;margin:18px 0"><div style="padding:16px;text-align:center;background:#fff"><b style="font-size:24px;color:${accent}">10+</b><small style="display:block;color:#64748b">Years</small></div><div style="padding:16px;text-align:center;background:#fff"><b style="font-size:24px;color:${accent}">500+</b><small style="display:block;color:#64748b">Customers</small></div><div style="padding:16px;text-align:center;background:#fff"><b style="font-size:24px;color:${accent}">4.9★</b><small style="display:block;color:#64748b">Rating</small></div><div style="padding:16px;text-align:center;background:#fff"><b style="font-size:24px;color:${accent}">24/7</b><small style="display:block;color:#64748b">Support</small></div></div>`;
    const nav=`<div style="padding:11px 16px;background:#fff;display:flex;align-items:center;gap:14px;border-bottom:1px solid ${bg}18;position:sticky;top:0;z-index:2"><div style="width:38px;height:38px;border-radius:12px;background:${bg};color:${accent};display:grid;place-items:center;font-weight:900">${esc((t.category||'B').slice(0,1))}</div><b style="margin-right:auto;color:${bg}">${esc(t.category||'YOUR BUSINESS')}</b><span style="font-size:10px">Home</span><span style="font-size:10px">About</span><span style="font-size:10px">Services</span><span style="font-size:10px">Contact</span></div>`;
    const cta=`<div style="margin:22px;padding:24px;border-radius:26px;background:linear-gradient(135deg,${bg},${accent});color:#fff;box-shadow:0 20px 45px #0003;display:grid;grid-template-columns:1fr .8fr;gap:16px;align-items:center"><div><div style="font-size:10px;letter-spacing:.16em;opacity:.75">READY TO CONNECT</div><h3 style="font-size:27px;margin:7px 0">${esc(t.cta||'Start Your Enquiry')}</h3><p style="opacity:.82;font-size:12px">Turn this page into a real lead-generation website.</p><button class="btn" style="background:${accent};color:#111;border:0">${esc(t.cta||'Enquire Now')} →</button></div><div style="background:#fff;border-radius:18px;padding:14px;color:#111"><b>Quick Enquiry</b><input class="input" placeholder="Full Name" style="margin-top:7px"><input class="input" placeholder="Mobile Number" style="margin-top:7px"><button class="btn primary" style="margin-top:7px;width:100%;background:${accent};color:#111">Send Lead</button></div></div>`;
